update public.learning_paths
set
  title = 'Statistics for the Behavioral Sciences',
  goal = 'Statistics for the Behavioral Sciences',
  summary = 'Frame statistics as disciplined reasoning about behavior, measurement, uncertainty, evidence, and ethical inference. Connect measurement and design, summarize distributions, build probability and estimation, test hypotheses with effect sizes and power, compare groups with t tests and ANOVA, handle categorical and nonparametric data, model correlation, regression, moderation, and mediation, introduce multilevel, factor, and missing-data methods, and synthesize through APA-style reporting and a capstone behavioral-science analysis.',
  data = $stbhjson${"slug": "statistics-for-the-behavioral-sciences", "title": "Statistics for the Behavioral Sciences", "description": "Frame statistics as disciplined reasoning about behavior, measurement, uncertainty, evidence, and ethical inference. Connect measurement and design, summarize distributions, build probability and estimation, test hypotheses with effect sizes and power, compare groups with t tests and ANOVA, handle categorical and nonparametric data, model correlation, regression, moderation, and mediation, introduce multilevel, factor, and missing-data methods, and synthesize through APA-style reporting and a capstone behavioral-science analysis.", "topics": [{"id": "fae003a4-00d3-4383-a8a3-9e4f80a472be", "type": "topic", "title": "Statistical Thinking for Behavioral Science", "description": "Frame statistics as disciplined reasoning about behavior, measurement, uncertainty, evidence, and ethical inference.", "children": [{"id": "27b822e0-78c8-4a7f-82d8-1613994cf965", "type": "subtopic", "title": "Why Statistics Matters", "children": [{"id": "4ba328ea-4c38-4bc8-a4a8-a61599b820a0", "type": "concept", "title": "Uncertainty"}, {"id": "42f87204-521b-4c06-9125-45e5100ee3a2", "type": "concept", "title": "Variation"}, {"id": "69957578-546a-45e4-8742-14027237c484", "type": "concept", "title": "Evidence"}, {"id": "29be150e-ed08-494a-bf79-35f43466d34f", "type": "concept", "title": "Inference from samples"}], "description": "Statistics helps behavioral scientists make careful claims from noisy, variable human data."}, {"id": "a843610f-efd3-4787-a6cf-1e433991e416", "type": "subtopic", "title": "Behavioral Science Questions", "children": [{"id": "c666de88-bc22-4a25-8a84-313f3edba307", "type": "concept", "title": "Description"}, {"id": "6a67b1f2-e770-41f7-b30a-a4276311bf43", "type": "concept", "title": "Group differences"}, {"id": "ef6c564a-2ebb-4fd3-85de-7a76b3eff733", "type": "concept", "title": "Association"}, {"id": "37810dc1-590f-40db-9ade-d536c0ea87f0", "type": "concept", "title": "Prediction and explanation"}], "description": "Statistical tools should follow from research questions about behavior, cognition, development, health, or social life."}, {"id": "1a4f187e-a96d-4ad3-a37b-92b7298fc895", "type": "subtopic", "title": "Responsible Inference", "children": [{"id": "5c0cc315-f64b-4ea0-929f-9e06638800d2", "type": "concept", "title": "Statistical vs practical significance"}, {"id": "0929e0ea-b0da-40b4-82b3-80cf1a5e082e", "type": "concept", "title": "Overclaiming"}, {"id": "87c07db1-3844-46bf-90a7-d1f18de790fc", "type": "concept", "title": "Replication"}, {"id": "a905ae44-6cc2-460f-bda7-f2be2696762d", "type": "concept", "title": "Transparency"}], "description": "Students learn that statistical results require judgment about design, assumptions, ethics, and consequences."}]}, {"id": "cab52aa0-d53f-472a-b4c2-e9e0063bbdf0", "type": "topic", "title": "Data, Measurement, Scales, and Research Design", "description": "Connect variables, measurement quality, study design, and data structure before any analysis begins.", "children": [{"id": "b61279e7-6c86-4abc-9163-6e9c8e843a0b", "type": "subtopic", "title": "Variables and Measurement Scales", "children": [{"id": "3de0f9d4-12b4-4c1f-8fde-2712054d719a", "type": "concept", "title": "Nominal"}, {"id": "7272ffeb-8c04-4369-a14c-716b79741b0f", "type": "concept", "title": "Ordinal"}, {"id": "e45830f6-4d07-4ab9-9780-07c27d84766a", "type": "concept", "title": "Interval and ratio"}, {"id": "74a26a92-b600-4e76-a910-7f6d49261e26", "type": "concept", "title": "Continuous vs categorical"}], "description": "The type of variable determines which summaries, graphs, and tests are appropriate."}, {"id": "e6f39144-29c2-4dcb-93b5-5513332a61a8", "type": "subtopic", "title": "Measurement Quality", "children": [{"id": "54161256-7df5-4371-b4ea-7ba5d4ed0f3c", "type": "concept", "title": "Reliability"}, {"id": "5fbc7d3e-4c1f-4bad-9389-b77c6511474b", "type": "concept", "title": "Validity"}, {"id": "29fa3bf8-9d35-4abd-a9e6-48f3c8c7174c", "type": "concept", "title": "Operational definitions"}, {"id": "23bb959d-7bf6-4fed-ace4-c660416e58b9", "type": "concept", "title": "Measurement error"}], "description": "Behavioral measures must be reliable, valid, and appropriate for the population and context."}, {"id": "e1ad278b-8fca-47f8-a104-437c8d3e9d57", "type": "subtopic", "title": "Design and Data Structure", "children": [{"id": "d84f915a-d46a-4cb5-abaf-03f62c11fb62", "type": "concept", "title": "Experimental design"}, {"id": "2608adc0-ec05-4470-a96a-da07854fe7d5", "type": "concept", "title": "Correlational design"}, {"id": "e8ee1e96-07f8-4e61-8bef-58603db70fc9", "type": "concept", "title": "Between-subjects and within-subjects"}, {"id": "1e9eeca9-fa48-4d5c-8d9c-cd1764d668ca", "type": "concept", "title": "Independence"}], "description": "Design choices shape what analyses can support and what causal claims are defensible."}]}, {"id": "c999b8c3-8ef5-4eff-8e5c-615eea4a431e", "type": "topic", "title": "Descriptive Statistics and Data Visualization", "description": "Summarize behavioral data clearly using distributions, center, variability, shape, and graphics.", "children": [{"id": "7348dacf-3352-4e33-b964-f8c362ef99dd", "type": "subtopic", "title": "Distributions", "children": [{"id": "684fb3c0-d56c-46c8-95a8-24228777aeb0", "type": "concept", "title": "Frequency tables"}, {"id": "25e92c05-9d63-419e-907d-867018141252", "type": "concept", "title": "Histograms"}, {"id": "d7d54cfb-646f-4ec7-bf8a-af67ede9a437", "type": "concept", "title": "Density plots"}, {"id": "e39e17e1-f933-48dc-a76c-9e1379bfd228", "type": "concept", "title": "Skew and outliers"}], "description": "Distributions reveal the pattern of scores before formal modeling begins."}, {"id": "056a971b-b64b-4516-a25a-3f8bf1d92553", "type": "subtopic", "title": "Center and Variability", "children": [{"id": "862155e4-90df-4fd6-a8da-b6a6d4b0ce29", "type": "concept", "title": "Mean and median"}, {"id": "348592bf-1cb5-444c-b8c9-8e75e662acff", "type": "concept", "title": "Mode"}, {"id": "824e2c29-5378-4ede-a9ff-38387cb48305", "type": "concept", "title": "Range and IQR"}, {"id": "621ecab1-1707-4b8f-ac29-6700f96e8016", "type": "concept", "title": "Variance and standard deviation"}], "description": "Descriptive statistics summarize typical performance and individual differences."}, {"id": "d4fd664c-66b5-47cf-aa1b-7a499e505bc4", "type": "subtopic", "title": "Behavioral Data Visualization", "children": [{"id": "e6bd158c-fe89-4c23-be5e-4d61f7e9f24d", "type": "concept", "title": "Bar charts with uncertainty"}, {"id": "dae060ea-4525-489c-a54b-35f0610132fb", "type": "concept", "title": "Boxplots and violin plots"}, {"id": "d7791844-b36c-45e4-97aa-e3d7164eef7a", "type": "concept", "title": "Scatterplots"}, {"id": "c166b15b-d3bb-4988-8dc9-dfdd94403f01", "type": "concept", "title": "Graphical integrity"}], "description": "Good graphs make patterns, uncertainty, and anomalies visible without misleading the reader."}]}, {"id": "a37f468a-f4aa-4763-a8ce-f22bfaf32bb4", "type": "topic", "title": "Probability, Random Variables, and the Normal Distribution", "description": "Build the probability foundation needed to reason about samples, uncertainty, and statistical models.", "children": [{"id": "b382008b-0121-4da9-b7e8-ba3e48642f09", "type": "subtopic", "title": "Probability Foundations", "children": [{"id": "108efbcf-48a7-4550-a926-22a18ddb2bf2", "type": "concept", "title": "Events"}, {"id": "05e516f3-9bab-4eef-aaab-f46383f264e9", "type": "concept", "title": "Complement and union"}, {"id": "15a1471c-0eef-441e-acb9-f5c999c74896", "type": "concept", "title": "Conditional probability"}, {"id": "7a019e4e-71bb-4bab-8194-16bbce4efc3e", "type": "concept", "title": "Independence"}], "description": "Probability gives the language for uncertainty, randomness, and long-run expectation."}, {"id": "eea1a656-c9ea-4737-9ea9-e2ee309bb0c9", "type": "subtopic", "title": "Random Variables and Distributions", "children": [{"id": "877551cb-aeb0-4dd7-98f9-b54947768710", "type": "concept", "title": "Discrete variables"}, {"id": "95daf030-b2bd-4ec5-99dc-55c0a6809205", "type": "concept", "title": "Continuous variables"}, {"id": "935977be-c2e9-4ef3-822e-925fb3771e35", "type": "concept", "title": "Expected value"}, {"id": "10b44d0c-a703-49c5-98c2-6e199b69f6f7", "type": "concept", "title": "Variance"}], "description": "Random variables connect possible outcomes to probabilities and model assumptions."}, {"id": "18dacde8-b8bf-48aa-a658-9c1a290accd5", "type": "subtopic", "title": "Normal Distribution", "children": [{"id": "8455a8da-06a9-4201-a129-92a8865601e5", "type": "concept", "title": "z scores"}, {"id": "fc312c37-d2c3-48a5-8b85-dfb6c200fdde", "type": "concept", "title": "Standard normal curve"}, {"id": "84eae117-3c0b-4a7b-be82-658e78c435c0", "type": "concept", "title": "Area under the curve"}, {"id": "d5bf896d-e405-41af-a593-5ab26cfa5ea4", "type": "concept", "title": "Normality assumptions"}], "description": "The normal distribution supports many behavioral-statistics procedures while requiring thoughtful use."}]}, {"id": "0adf4a2a-b2b0-4145-88bc-44da2b7fdf67", "type": "topic", "title": "Sampling Distributions, Estimation, and Confidence Intervals", "description": "Explain how sample statistics vary and how intervals communicate uncertainty about population values.", "children": [{"id": "ec18cfd6-b7ec-4afe-a04c-cb81d86cf335", "type": "subtopic", "title": "Sampling Logic", "children": [{"id": "4ceba24d-efcd-412f-b848-637e29819914", "type": "concept", "title": "Population vs sample"}, {"id": "8e3b168f-288b-4a97-9a34-cb2a96af8a39", "type": "concept", "title": "Sampling variability"}, {"id": "32e12b60-3490-4b27-b1bf-be561482848b", "type": "concept", "title": "Central limit theorem"}, {"id": "abad7642-868d-4201-972b-e89b46ee9e0e", "type": "concept", "title": "Standard error"}], "description": "Sampling distributions explain why sample results differ and how much random error to expect."}, {"id": "8f93b12f-e423-4642-8ee0-17409ba10097", "type": "subtopic", "title": "Estimation", "children": [{"id": "f251b38e-3cfd-4315-b263-5565f2b6598d", "type": "concept", "title": "Point estimates"}, {"id": "ec0a60d8-9759-4d19-b0b9-2f15cc9a59dc", "type": "concept", "title": "Interval estimates"}, {"id": "b6a29fd5-6f33-46c6-bf29-66d6a0be7fab", "type": "concept", "title": "Precision"}, {"id": "1fad76a4-aa17-4cea-b4a1-7a096654991c", "type": "concept", "title": "Bias"}], "description": "Estimation shifts attention from yes/no decisions to plausible values for population effects."}, {"id": "a4634135-ec6a-4882-bd62-1321e6712baf", "type": "subtopic", "title": "Confidence Intervals", "children": [{"id": "1429f237-6820-403c-87b4-cf9469e07e2d", "type": "concept", "title": "Confidence level"}, {"id": "068dc0cb-ad39-4617-87ba-b1d2f5460de2", "type": "concept", "title": "Margin of error"}, {"id": "17815b01-3ec0-4e11-b53b-d17fefff897b", "type": "concept", "title": "Intervals for means"}, {"id": "ddef96a6-40be-40c3-b420-40c3595af387", "type": "concept", "title": "Intervals for differences"}], "description": "Confidence intervals communicate uncertainty and support effect-size interpretation."}]}, {"id": "d1adeaa4-b373-4c64-ac49-bbcb3165dfd7", "type": "topic", "title": "Hypothesis Testing, p-Values, Effect Sizes, and Power", "description": "Use tests responsibly while emphasizing practical importance, uncertainty, and study planning.", "children": [{"id": "5480c873-257f-426c-837b-a8ef3ea406e9", "type": "subtopic", "title": "Null Hypothesis Significance Testing", "children": [{"id": "5cdd61c7-c814-439d-a0be-ab3b5cd7b71d", "type": "concept", "title": "Null and alternative hypotheses"}, {"id": "76d2d84a-58b9-4416-ac2b-a96cca914a97", "type": "concept", "title": "Test statistics"}, {"id": "286752be-0eea-4efb-bbeb-ad0b509b953e", "type": "concept", "title": "p-values"}, {"id": "3806a0f9-701a-47c3-b663-3838c6ac3d51", "type": "concept", "title": "Decision errors"}], "description": "Hypothesis testing compares observed data to what would be expected under a null model."}, {"id": "2e0e99e1-4bdc-4a56-a54f-fa14e6152a5f", "type": "subtopic", "title": "Effect Sizes", "children": [{"id": "f14f37b0-e897-4feb-b17e-32a3ce8fccbf", "type": "concept", "title": "Cohen's d"}, {"id": "a327576a-cdb9-47e8-9c6b-63d074decfa3", "type": "concept", "title": "Eta squared"}, {"id": "3f274350-2ebd-432b-8456-18f534bc3d23", "type": "concept", "title": "Correlation effect sizes"}, {"id": "3f467baf-2676-4b11-a116-c7694891e4a5", "type": "concept", "title": "Interpretation in context"}], "description": "Effect sizes answer how large an effect is, not only whether it is unlikely under a null."}, {"id": "1d27c2fe-41ed-4867-bd70-0b55afe9d098", "type": "subtopic", "title": "Power and Study Planning", "children": [{"id": "7decfe36-3d97-4784-873f-47ffb61eb651", "type": "concept", "title": "Type I error"}, {"id": "c58e9cb7-7959-4738-a4a9-c96d76997078", "type": "concept", "title": "Type II error"}, {"id": "c4f1aa63-4959-422a-8895-582e2e7bba34", "type": "concept", "title": "Power"}, {"id": "72fefa95-591a-4f60-af56-e4cda1e93685", "type": "concept", "title": "A priori vs post hoc power"}], "description": "Power analysis links sample size, effect size, alpha, and the chance of detecting meaningful effects."}]}, {"id": "a3fe8b2a-12c5-4edd-9f37-6170193032c6", "type": "topic", "title": "z Tests, One-Sample t Tests, and Paired-Samples Designs", "description": "Analyze single-group, benchmark, and within-person research questions common in psychology.", "children": [{"id": "15b66385-2100-4eea-b5e1-ecdac6d3418a", "type": "subtopic", "title": "One-Sample Inference", "children": [{"id": "662998ba-854a-4000-9194-053125385df2", "type": "concept", "title": "z test logic"}, {"id": "bc7ad317-0951-416f-a0ed-a16bf92cb900", "type": "concept", "title": "One-sample t test"}, {"id": "05241ab6-e435-44c3-ae57-724a574fe0d1", "type": "concept", "title": "Degrees of freedom"}, {"id": "628c0d39-9e53-4e67-ba6d-356bac40b09a", "type": "concept", "title": "Confidence interval for a mean"}], "description": "One-sample procedures test whether a sample differs from a known or hypothesized benchmark."}, {"id": "c9dac470-9527-4ab6-a2b2-e608ca1f5d89", "type": "subtopic", "title": "Paired-Samples Designs", "children": [{"id": "196ffb58-88bb-4d7e-86a2-083317e1f8ce", "type": "concept", "title": "Pre-post designs"}, {"id": "8971bd2c-7e54-4dba-ae49-4f0b0962656f", "type": "concept", "title": "Matched pairs"}, {"id": "b86cb42a-5336-4b3f-802c-e299b709ab4b", "type": "concept", "title": "Difference scores"}, {"id": "10f924ca-06bc-4c08-b5c3-e30371ce99cd", "type": "concept", "title": "Within-person effect size"}], "description": "Paired tests analyze change or matched observations while accounting for dependence."}, {"id": "8d49e1fa-7f50-437f-9344-f0f38e5ce402", "type": "subtopic", "title": "Assumptions and Interpretation", "children": [{"id": "bfd2ab2b-b601-43e7-9faa-f708dedae0ae", "type": "concept", "title": "Normality of differences"}, {"id": "7a769667-5743-44af-b536-2cf43bbab25d", "type": "concept", "title": "Outliers"}, {"id": "e065ab33-7d1f-4dba-9408-0d8954a40398", "type": "concept", "title": "Independence of cases"}, {"id": "99e0f5e3-8407-4461-87ce-2103d99417c4", "type": "concept", "title": "APA-style results"}], "description": "Students learn to check whether the design and data justify the test."}]}, {"id": "2ef2fed0-c698-4daa-a9c2-62440607077a", "type": "topic", "title": "Independent-Samples t Tests and Group Comparisons", "description": "Compare two independent groups while checking assumptions, effect sizes, and design limitations.", "children": [{"id": "3a10ede8-13c2-4ba3-977e-91f841acbba8", "type": "subtopic", "title": "Two-Group Designs", "children": [{"id": "55c24863-0548-42b5-9e1c-2649bda0caec", "type": "concept", "title": "Treatment vs control"}, {"id": "91b78c72-4876-4f17-b9ee-c9d8bb47d474", "type": "concept", "title": "Naturally occurring groups"}, {"id": "1a204d1f-ac08-4f3b-833b-4445170dcf08", "type": "concept", "title": "Random assignment"}, {"id": "29b7fa33-9bc9-47e0-a6ec-2fc8a44e1436", "type": "concept", "title": "Group means"}], "description": "Independent-samples t tests support basic experimental and quasi-experimental comparisons."}, {"id": "1ad1e6ac-59b0-4cd7-b290-7e873f112cba", "type": "subtopic", "title": "Assumptions and Alternatives", "children": [{"id": "cf3fc363-1495-4d7a-8614-904ef994f12b", "type": "concept", "title": "Homogeneity of variance"}, {"id": "4314cbb4-bfa8-4fa4-95a7-4fafaf86b521", "type": "concept", "title": "Welch t test"}, {"id": "2125fd82-41c9-4559-9276-a3c8fd94e297", "type": "concept", "title": "Outliers"}, {"id": "4b5cb87e-c4d1-4421-8fc2-93e48e0cc477", "type": "concept", "title": "Nonparametric alternatives"}], "description": "Assumption checks protect interpretation and guide robust alternatives."}, {"id": "de01e78e-b9a9-448c-8d91-524fa08639ba", "type": "subtopic", "title": "Reporting Group Differences", "children": [{"id": "fcfde1f1-6332-4af3-a7b7-1a6ced301505", "type": "concept", "title": "Mean difference"}, {"id": "2cf99c9d-0d66-4f1d-96b4-4ceaf7a9ca64", "type": "concept", "title": "Cohen's d"}, {"id": "88fabcf3-eac9-4aad-b886-67a2a7323db8", "type": "concept", "title": "Confidence interval"}, {"id": "b536cfaf-7dc5-4bb4-ace5-6b7b9623ff24", "type": "concept", "title": "Interpretive caution"}], "description": "Strong reports combine test statistics, intervals, effect sizes, design context, and limitations."}]}, {"id": "23256490-438b-47de-8e05-7b3480b9d79a", "type": "topic", "title": "One-Way ANOVA, Post-Hoc Tests, and Planned Contrasts", "description": "Extend group comparison to three or more conditions and interpret omnibus and targeted effects.", "children": [{"id": "2a5cd656-f694-4eca-9a61-16886d48ca50", "type": "subtopic", "title": "ANOVA Logic", "children": [{"id": "81baa3cd-02cf-43a3-bd72-240f3d3e610b", "type": "concept", "title": "F statistic"}, {"id": "068f7170-c9e4-4fbe-a9f4-873dbd2f7793", "type": "concept", "title": "Between-group variance"}, {"id": "040becf0-c858-4d12-86e9-66cfb500b508", "type": "concept", "title": "Within-group variance"}, {"id": "71fb7862-d832-4610-8435-d6d96f204a45", "type": "concept", "title": "Omnibus test"}], "description": "ANOVA compares variation between groups to variation within groups."}, {"id": "94b28010-3870-4500-a116-b2cee7ba44ed", "type": "subtopic", "title": "Post-Hoc Tests and Contrasts", "children": [{"id": "2a0c2c52-67a7-4b39-ab2a-350c50cd680b", "type": "concept", "title": "Tukey HSD"}, {"id": "9a5671d6-841d-4a1a-ad46-21beb813bae2", "type": "concept", "title": "Bonferroni"}, {"id": "cd0dbd9d-4795-4dbb-8321-1d39e887f15b", "type": "concept", "title": "Planned contrasts"}, {"id": "cc1f9fe7-ac67-4fc5-920f-d94635dd3e31", "type": "concept", "title": "Familywise error"}], "description": "Follow-up tests identify where differences lie while controlling error thoughtfully."}, {"id": "8fa093f8-13d4-451b-86d0-a1a0496250f7", "type": "subtopic", "title": "Effect Size and Assumptions", "children": [{"id": "a85bbb91-c8e7-4373-b159-3388a3bb5a24", "type": "concept", "title": "Eta squared"}, {"id": "234b23ad-6b06-40bc-a49a-d60e46f4f555", "type": "concept", "title": "Omega squared"}, {"id": "51839293-6636-4a9f-9928-a97d748a6c85", "type": "concept", "title": "Residuals"}, {"id": "07bfe359-37d9-4ac9-9c49-0c3cb6e10f09", "type": "concept", "title": "Homogeneity of variance"}], "description": "ANOVA interpretation depends on assumption checks and meaningful effect-size reporting."}]}, {"id": "a86ba9c6-edcd-4459-83db-abf1d761f8ec", "type": "topic", "title": "Factorial and Repeated-Measures ANOVA", "description": "Analyze designs with multiple factors, interactions, and repeated observations from the same participants.", "children": [{"id": "8759ef59-da07-4de0-b685-35a6fe996486", "type": "subtopic", "title": "Factorial Designs", "children": [{"id": "d3333ba9-337e-489c-854b-fe2a2540ffae", "type": "concept", "title": "Main effects"}, {"id": "30f4c9df-488c-430f-917d-948a2e279e9f", "type": "concept", "title": "Interactions"}, {"id": "1cbb5ddd-dd8f-4bd2-b910-1480bdba711c", "type": "concept", "title": "Simple effects"}, {"id": "06f3bee9-04c7-4cc4-a4b4-2f564de63d5d", "type": "concept", "title": "Cell means"}], "description": "Factorial ANOVA tests multiple independent variables and whether their effects depend on each other."}, {"id": "ac935efd-2601-4736-877b-9472daec1ba6", "type": "subtopic", "title": "Repeated-Measures Designs", "children": [{"id": "deb1d1d6-c2a1-4b6a-8827-c26ce8f00dd9", "type": "concept", "title": "Within-subject factors"}, {"id": "218e95be-0b5c-44e9-8268-48e1185e4c14", "type": "concept", "title": "Sphericity"}, {"id": "fd7dd3dc-f3e7-4c93-a8d2-df3ac68337bc", "type": "concept", "title": "Greenhouse-Geisser correction"}, {"id": "817e971e-f3ca-47de-9e75-a124ee2fce6e", "type": "concept", "title": "Carryover effects"}], "description": "Repeated-measures ANOVA handles multiple observations from the same participants."}, {"id": "eee41775-0d61-4e68-9858-21c64fce2a62", "type": "subtopic", "title": "Mixed Designs", "children": [{"id": "138d9909-2f53-4b95-9107-208ca57fddf5", "type": "concept", "title": "Split-plot designs"}, {"id": "2923ef86-3a6b-4cfb-9c8f-5e3c182b3fa9", "type": "concept", "title": "Time by group interaction"}, {"id": "7920eb05-d3ea-45d4-ab0e-e7418f481802", "type": "concept", "title": "Participant variability"}, {"id": "d2962853-9972-4957-a77d-ac1c02ecbf04", "type": "concept", "title": "Graphing interactions"}], "description": "Mixed designs combine between-person and within-person factors common in behavioral experiments."}]}, {"id": "cbe0a58a-4a8a-4bf7-835e-e708f0c94b7d", "type": "topic", "title": "Categorical Data, Chi-Square Tests, and Nonparametric Methods", "description": "Handle counts, categories, ordinal outcomes, assumption violations, and robust alternatives.", "children": [{"id": "816b0684-dff3-4be8-8aff-0c5290678d24", "type": "subtopic", "title": "Categorical Data", "children": [{"id": "59f94763-d971-45be-b6ad-d605d18ee185", "type": "concept", "title": "Contingency tables"}, {"id": "a4ac16df-5dac-4ef9-b35d-3a8f3125d3b8", "type": "concept", "title": "Expected frequencies"}, {"id": "3a342f8e-da88-4392-afb4-04088033a240", "type": "concept", "title": "Proportions"}, {"id": "b2ef745d-fb27-482b-a7e3-455455f938b1", "type": "concept", "title": "Risk and odds"}], "description": "Many behavioral outcomes are counts, categories, diagnoses, choices, or classifications."}, {"id": "6aab1ca2-72d3-41ec-851d-a45d16e8cce2", "type": "subtopic", "title": "Chi-Square Tests", "children": [{"id": "4b920df5-8cd4-4758-a399-0aea6b0fb53d", "type": "concept", "title": "Goodness of fit"}, {"id": "78420942-43b7-41fe-92b3-ff52d0d151ed", "type": "concept", "title": "Test of independence"}, {"id": "597f93a9-3c50-4db5-adad-494c431675e5", "type": "concept", "title": "Standardized residuals"}, {"id": "c76662c3-fdeb-41d9-8204-20d1ab4b3e5d", "type": "concept", "title": "Cramer's V"}], "description": "Chi-square methods test association or goodness of fit for categorical patterns."}, {"id": "a3845301-92fb-4c72-8242-2d4d7a7970c5", "type": "subtopic", "title": "Nonparametric and Robust Methods", "children": [{"id": "0b8a75fc-ccae-43fe-9143-5ada76881be3", "type": "concept", "title": "Mann-Whitney U"}, {"id": "c3a21523-afa3-4f9f-9fd7-94c5c950fa73", "type": "concept", "title": "Wilcoxon signed-rank"}, {"id": "787fe978-d194-4d76-9a10-e65bb4c5cfa5", "type": "concept", "title": "Kruskal-Wallis"}, {"id": "c715b5b6-bba8-407d-9669-45e55e64c604", "type": "concept", "title": "Permutation logic"}], "description": "Nonparametric tests help when data are ordinal, skewed, or assumption-challenged."}]}, {"id": "fe173a9a-6b31-497b-aabe-38d8bed4d4d7", "type": "topic", "title": "Correlation, Simple Regression, and Prediction", "description": "Model associations and prediction while distinguishing correlation, causation, and practical fit.", "children": [{"id": "b16c3e33-599a-4738-be55-0456b2e71032", "type": "subtopic", "title": "Correlation", "children": [{"id": "1811bbe9-aeaa-4f9a-a78b-632dc496cc1e", "type": "concept", "title": "Pearson r"}, {"id": "97eb1a7f-7971-47cf-905e-b53a3e64e9df", "type": "concept", "title": "Spearman rho"}, {"id": "f0529816-9166-4459-8945-a99dfe1b1b39", "type": "concept", "title": "Scatterplots"}, {"id": "cc08bda4-c4c4-4d43-8075-a9d54dd215d6", "type": "concept", "title": "Restriction of range"}], "description": "Correlation measures the direction and strength of linear association between variables."}, {"id": "63aae276-6924-4d92-aa72-603fabf56c65", "type": "subtopic", "title": "Simple Linear Regression", "children": [{"id": "0ae0bf7e-5a5a-4fd4-85a4-f5adb6b917c7", "type": "concept", "title": "Slope and intercept"}, {"id": "f4deda1c-1c5a-40a4-988b-2c021a154896", "type": "concept", "title": "Residuals"}, {"id": "c821b14b-141c-4da3-b79b-4fd1fdbbf275", "type": "concept", "title": "R squared"}, {"id": "0b94f1f9-65e0-48e8-9656-3d5850ee64c3", "type": "concept", "title": "Prediction intervals"}], "description": "Regression models expected outcomes from predictors and introduces prediction error."}, {"id": "493674da-e778-44ac-a0cb-0517a9351299", "type": "subtopic", "title": "Correlation vs Causation", "children": [{"id": "47917a90-5289-4614-bc0f-84ca464b5fdf", "type": "concept", "title": "Confounding"}, {"id": "55c379b8-9596-491d-af3a-9374edc2edda", "type": "concept", "title": "Third variables"}, {"id": "1dc179a8-7c7e-4ee3-8b77-a481a9175d81", "type": "concept", "title": "Directionality"}, {"id": "db9e8e97-8f40-436d-ab00-aa2c3b28fad0", "type": "concept", "title": "Design-based causal inference"}], "description": "Behavioral scientists must separate association from causal explanation."}]}, {"id": "6091c228-df37-4daa-93e4-0e64b4a6d999", "type": "topic", "title": "Multiple Regression, GLM, Moderation, and Mediation", "description": "Move from bivariate relationships to richer behavioral models with multiple predictors and mechanisms.", "children": [{"id": "